<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $print ? 'POS Receipt' : 'Customer Invoice' }} · {{ $customer->customer_unique_id }}</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f3f4f6}.paper{max-width:850px;margin:30px auto;background:#fff;padding:36px;border:1px solid #e5e7eb}.brand{color:#b90f2f;font-weight:800;font-size:24px}.muted{color:#6b7280}@media print{body{background:#fff}.paper{margin:0 auto;border:0;max-width:none;padding:10mm}.no-print{display:none!important}}</style></head><body><main class="paper"><div class="d-flex justify-content-between border-bottom pb-3 mb-4"><div><div class="brand">{{ siteUrlSettings('site_name') ?: 'X-Link LTD' }}</div><div class="muted">{{ $print ? 'POS Payment Receipt' : 'Customer Invoice / Billing Statement' }}</div></div><div class="text-end"><strong>{{ $print ? 'RECEIPT' : 'INVOICE' }}</strong><div>{{ now()->format('d M Y, h:i A') }}</div><div class="muted">Customer ID: {{ $customer->customer_unique_id }}</div></div></div><div class="row mb-4"><div class="col-7"><h5 class="mb-1">{{ $customer->customer_name }}</h5><div>{{ $customer->mobile ?: '—' }}</div><div>{{ $customer->address ?: '—' }}</div><div>PPPoE: {{ $customer->pppUser?->username ?: '—' }}</div></div><div class="col-5 text-end"><div>Package: <strong>{{ $customer->package?->package ?: '—' }}</strong></div><div>Expiry: <strong>{{ $customer->billing?->auto_disable_date ? \Carbon\Carbon::parse($customer->billing->auto_disable_date)->format('d M Y') : '—' }}</strong></div></div></div><table class="table table-bordered"><thead class="table-light"><tr><th>Description</th><th class="text-end">Amount (৳)</th></tr></thead><tbody><tr><td>Monthly Rent</td><td class="text-end">{{ number_format((float)($customer->billing?->monthly_rent??0),2) }}</td></tr><tr><td>Additional Charge</td><td class="text-end